// Automatisch erzeugt aus web/index.html – nicht von Hand bearbeiten.
const html: string = "<!DOCTYPE html>\n<html lang=\"de-CH\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Naki Bodenplaner – Traumboden virtuell verlegen</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;9..144,650&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --bg:#f5f1ea; --panel:#fffdf9; --ink:#2a231c; --muted:#7a6d60; --line:#e6ddd0;\n  --accent:#8a5a2b; --accent-2:#b57a3e; --accent-soft:#f1e4d3; --ok:#3f7a4a; --danger:#a33b2b;\n  --radius:14px; --shadow:0 6px 24px rgba(60,40,20,.10);\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;height:100%}\nbody{font-family:Inter,system-ui,sans-serif;background:var(--bg);color:var(--ink);font-size:15px;-webkit-font-smoothing:antialiased}\nbutton,input,select,textarea{font:inherit;color:inherit}\nbutton{cursor:pointer}\nheader{display:flex;align-items:center;justify-content:space-between;padding:12px 18px;background:var(--panel);border-bottom:1px solid var(--line);position:sticky;top:0;z-index:20}\n.brand{display:flex;align-items:center;gap:10px}\n.logo{width:34px;height:34px;border-radius:9px;background:\n  repeating-linear-gradient(90deg,#b57a3e 0 6px,#9c6530 6px 7px,#c48a4c 7px 13px,#8a5a2b 13px 14px);box-shadow:inset 0 0 0 1px rgba(0,0,0,.08)}\n.brand h1{font-family:Fraunces,serif;font-weight:650;font-size:19px;margin:0;letter-spacing:-.01em}\n.brand small{display:block;font-size:11.5px;color:var(--muted);font-weight:500;letter-spacing:.02em}\n.hdr-actions{display:flex;gap:8px}\n.chip-btn{border:1px solid var(--line);background:#fff;border-radius:999px;padding:7px 13px;font-size:13.5px;font-weight:500;display:inline-flex;align-items:center;gap:6px}\n.chip-btn:hover{border-color:var(--accent-2)}\n.chip-btn .count{background:var(--accent);color:#fff;border-radius:999px;font-size:11px;padding:1px 7px}\n\nmain{display:grid;grid-template-columns:minmax(0,1fr) 380px;gap:18px;padding:18px;max-width:1500px;margin:0 auto}\n@media (max-width:960px){main{grid-template-columns:1fr;padding:10px;gap:10px}}\n\n.stage-wrap{background:#1d1814;border-radius:var(--radius);box-shadow:var(--shadow);padding:10px;display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:300px;position:relative}\n.stage{position:relative;width:100%;touch-action:none;user-select:none;-webkit-user-select:none}\n.stage canvas{display:block;width:100%;height:auto;border-radius:8px}\n.overlay{position:absolute;inset:0;pointer-events:none}\n.overlay svg{position:absolute;inset:0;width:100%;height:100%;overflow:visible}\n.handle{position:absolute;width:30px;height:30px;margin:-15px 0 0 -15px;border-radius:50%;background:rgba(255,255,255,.95);border:3px solid var(--accent-2);box-shadow:0 2px 10px rgba(0,0,0,.45);pointer-events:auto;cursor:grab;touch-action:none;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:600;color:var(--accent)}\n.handle:active{cursor:grabbing;transform:scale(1.12)}\n.overlay.hidden .handle,.overlay.hidden svg{display:none}\n.split-line{position:absolute;top:0;bottom:0;width:3px;margin-left:-1.5px;background:#fff;box-shadow:0 0 8px rgba(0,0,0,.6);pointer-events:auto;cursor:ew-resize;display:none;touch-action:none}\n.split-line::after{content:\"⟷\";position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);background:#fff;color:var(--accent);border-radius:999px;width:34px;height:34px;display:flex;align-items:center;justify-content:center;font-weight:700;box-shadow:0 2px 8px rgba(0,0,0,.4)}\n.split-line.on{display:block}\n.split-tag{position:absolute;top:10px;padding:3px 9px;border-radius:999px;background:rgba(0,0,0,.55);color:#fff;font-size:12px;display:none}\n.split-on .split-tag{display:block}\n.stage-tools{display:flex;gap:8px;flex-wrap:wrap;justify-content:center;margin-top:10px;width:100%}\n.tool{background:rgba(255,255,255,.1);color:#f3ebe0;border:1px solid rgba(255,255,255,.16);border-radius:999px;padding:8px 14px;font-size:13.5px;font-weight:500;display:inline-flex;align-items:center;gap:7px}\n.tool:hover{background:rgba(255,255,255,.18)}\n.tool.active{background:#f3ebe0;color:#2a231c}\n.tool.primary{background:var(--accent-2);border-color:var(--accent-2);color:#fff}\n.tool.primary:hover{background:var(--accent)}\n.hint{position:absolute;left:50%;top:18px;transform:translateX(-50%);background:rgba(20,15,10,.78);color:#fff;padding:7px 14px;border-radius:999px;font-size:13px;pointer-events:none;white-space:nowrap;transition:opacity .4s;max-width:92%;overflow:hidden;text-overflow:ellipsis}\n.busy{position:absolute;inset:0;display:none;align-items:center;justify-content:center;background:rgba(20,15,10,.35);border-radius:var(--radius);color:#fff;font-weight:500;gap:10px;z-index:5}\n.busy.on{display:flex}\n.spinner{width:22px;height:22px;border-radius:50%;border:3px solid rgba(255,255,255,.3);border-top-color:#fff;animation:spin .8s linear infinite}\n@keyframes spin{to{transform:rotate(360deg)}}\n\naside.panel{background:var(--panel);border-radius:var(--radius);box-shadow:var(--shadow);display:flex;flex-direction:column;overflow:hidden;max-height:calc(100vh - 100px);position:sticky;top:78px}\n@media (max-width:960px){aside.panel{max-height:none;position:static}}\n.steps{display:grid;grid-template-columns:repeat(4,1fr);border-bottom:1px solid var(--line)}\n.step{background:none;border:0;padding:12px 4px 10px;display:flex;flex-direction:column;align-items:center;gap:4px;font-size:12.5px;font-weight:500;color:var(--muted);border-bottom:2px solid transparent}\n.step .n{width:24px;height:24px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:var(--accent-soft);color:var(--accent);font-size:12px;font-weight:600}\n.step.active{color:var(--ink);border-bottom-color:var(--accent-2)}\n.step.active .n{background:var(--accent-2);color:#fff}\n.pane{display:none;padding:16px;overflow:auto}\n.pane.active{display:block}\n.pane h2{font-family:Fraunces,serif;font-weight:600;font-size:20px;margin:2px 0 6px}\n.pane p.lead{color:var(--muted);margin:0 0 14px;line-height:1.5;font-size:14px}\n.big-btn{width:100%;display:flex;align-items:center;gap:12px;padding:14px;border:1.5px dashed var(--accent-2);background:var(--accent-soft);border-radius:12px;text-align:left;margin-bottom:10px}\n.big-btn.solid{border-style:solid;background:#fff;border-color:var(--line)}\n.big-btn:hover{border-color:var(--accent)}\n.big-btn .ic{width:40px;height:40px;border-radius:10px;background:#fff;display:flex;align-items:center;justify-content:center;flex:none;font-size:20px}\n.big-btn b{display:block;font-weight:600}\n.big-btn span{font-size:13px;color:var(--muted)}\n.howto{list-style:none;padding:0;margin:16px 0 0;display:grid;gap:10px}\n.howto li{display:flex;gap:10px;font-size:13.5px;line-height:1.45;color:#4b4036}\n.howto li i{font-style:normal;flex:none;width:22px;height:22px;border-radius:50%;background:var(--accent-soft);color:var(--accent);display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:600}\n\n.filters{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:12px}\n.filter{border:1px solid var(--line);background:#fff;border-radius:999px;padding:6px 12px;font-size:13px;font-weight:500}\n.filter.active{background:var(--ink);color:#fff;border-color:var(--ink)}\n.tone{display:flex;gap:6px;margin-bottom:12px;font-size:12.5px;color:var(--muted);align-items:center}\n.tone .filter{padding:4px 10px;font-size:12.5px}\n.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}\n@media (max-width:960px){.grid{grid-template-columns:repeat(auto-fill,minmax(150px,1fr))}}\n.card{background:#fff;border:1.5px solid var(--line);border-radius:12px;padding:0;overflow:hidden;text-align:left;transition:border-color .15s,transform .15s}\n.card:hover{transform:translateY(-1px);border-color:#d6c6b0}\n.card.active{border-color:var(--accent-2);box-shadow:0 0 0 3px var(--accent-soft)}\n.card canvas{display:block;width:100%;aspect-ratio:4/3;background:#eee}\n.card .meta{padding:8px 10px 10px}\n.card .meta b{display:block;font-size:13.5px;font-weight:600;line-height:1.25}\n.card .meta span{font-size:12px;color:var(--muted)}\n.tag{display:inline-block;font-size:10.5px;font-weight:600;letter-spacing:.04em;text-transform:uppercase;color:var(--accent);background:var(--accent-soft);padding:2px 7px;border-radius:6px;margin-bottom:4px}\n\n.field{margin-bottom:16px}\n.field label.t{display:flex;justify-content:space-between;font-weight:600;font-size:13.5px;margin-bottom:8px}\n.field label.t output{font-weight:500;color:var(--muted)}\n.seg{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin-bottom:8px}\n.seg button{border:1px solid var(--line);background:#fff;border-radius:10px;padding:8px 0;font-size:13px;font-weight:500;display:flex;flex-direction:column;align-items:center;gap:3px}\n.seg button svg{width:22px;height:22px}\n.seg button.active{border-color:var(--accent-2);background:var(--accent-soft)}\ninput[type=range]{width:100%;accent-color:var(--accent-2)}\n.dims{display:grid;grid-template-columns:1fr 1fr;gap:10px}\n.dims label{font-size:12.5px;color:var(--muted);display:block;margin-bottom:4px}\n.inp{width:100%;border:1px solid var(--line);border-radius:10px;padding:9px 11px;background:#fff}\n.inp:focus{outline:2px solid var(--accent-soft);border-color:var(--accent-2)}\n.area{margin-top:8px;font-size:13px;color:var(--muted)}\n.area b{color:var(--ink)}\n.toggle-row{display:flex;justify-content:space-between;align-items:center;padding:10px 0;border-top:1px solid var(--line);font-size:14px}\n.switch{position:relative;width:44px;height:26px;flex:none}\n.switch input{opacity:0;width:0;height:0}\n.switch span{position:absolute;inset:0;background:#d8cfc2;border-radius:999px;transition:.2s}\n.switch span::before{content:\"\";position:absolute;width:20px;height:20px;left:3px;top:3px;background:#fff;border-radius:50%;transition:.2s;box-shadow:0 1px 3px rgba(0,0,0,.2)}\n.switch input:checked+span{background:var(--accent-2)}\n.switch input:checked+span::before{transform:translateX(18px)}\n\n.saved{display:grid;gap:12px}\n.saved-item{border:1px solid var(--line);border-radius:12px;overflow:hidden;background:#fff}\n.saved-item img{display:block;width:100%;aspect-ratio:16/10;object-fit:cover;background:#ddd}\n.saved-item .meta{padding:10px 12px}\n.saved-item .meta b{font-weight:600}\n.saved-item .meta small{display:block;color:var(--muted);font-size:12px;margin-top:2px}\n.saved-item .acts{display:flex;flex-wrap:wrap;gap:6px;padding:0 12px 12px}\n.mini{border:1px solid var(--line);background:#fff;border-radius:999px;padding:6px 11px;font-size:12.5px;font-weight:500}\n.mini.pri{background:var(--accent-2);border-color:var(--accent-2);color:#fff}\n.mini.del{color:var(--danger)}\n.empty{text-align:center;padding:30px 10px;color:var(--muted);font-size:14px;line-height:1.5}\n.empty .e-ic{font-size:34px;margin-bottom:8px}\n.cta-box{margin-top:16px;padding:14px;border-radius:12px;background:var(--accent-soft);font-size:13.5px;line-height:1.5}\n.cta-box b{display:block;margin-bottom:4px}\n\n.modal{position:fixed;inset:0;background:rgba(25,18,12,.55);display:none;align-items:center;justify-content:center;z-index:100;padding:14px}\n.modal.on{display:flex}\n.dialog{background:var(--panel);border-radius:16px;max-width:520px;width:100%;max-height:92vh;overflow:auto;box-shadow:0 20px 60px rgba(0,0,0,.3)}\n.dialog .dh{display:flex;justify-content:space-between;align-items:center;padding:16px 18px;border-bottom:1px solid var(--line)}\n.dialog .dh h3{margin:0;font-family:Fraunces,serif;font-weight:600;font-size:19px}\n.x{border:0;background:none;font-size:24px;line-height:1;color:var(--muted)}\n.dialog .db{padding:16px 18px}\n.dialog .db .row{display:grid;grid-template-columns:1fr 1fr;gap:10px}\n.dialog .db label{display:block;font-size:12.5px;color:var(--muted);margin:10px 0 4px}\n.dialog .df{display:flex;justify-content:flex-end;gap:8px;padding:0 18px 18px}\n.btn{border:1px solid var(--line);background:#fff;border-radius:10px;padding:10px 16px;font-weight:600}\n.btn.pri{background:var(--accent-2);color:#fff;border-color:var(--accent-2)}\n.btn.pri:hover{background:var(--accent)}\n.summary{background:#fff;border:1px solid var(--line);border-radius:10px;padding:12px;font-size:13px;white-space:pre-wrap;line-height:1.5;max-height:260px;overflow:auto;font-family:ui-monospace,Menlo,monospace}\n.share-img{width:100%;border-radius:10px;display:block;margin-bottom:10px}\n.note{font-size:12.5px;color:var(--muted);line-height:1.5;margin-top:10px}\n.toast{position:fixed;left:50%;bottom:24px;transform:translateX(-50%) translateY(30px);background:var(--ink);color:#fff;padding:11px 18px;border-radius:999px;font-size:14px;opacity:0;transition:.3s;z-index:200;pointer-events:none}\n.toast.on{opacity:1;transform:translateX(-50%) translateY(0)}\nfooter{text-align:center;color:var(--muted);font-size:12.5px;padding:6px 0 24px}\nfooter a{color:var(--accent)}\n.hdr-label{}\n@media (max-width:520px){.brand small{display:none}.brand h1{font-size:17px}.hdr-label{display:none}}\n.in-app header{position:sticky;top:0}\n.in-app footer{padding-bottom:12px}\n.in-app .card:hover{transform:none}\n.nogl{color:#fff;padding:40px;text-align:center;line-height:1.6}\n</style>\n</head>\n<body>\n<header>\n  <div class=\"brand\">\n    <div class=\"logo\" aria-hidden=\"true\"></div>\n    <div><h1>Naki Bodenplaner</h1><small>Traumboden virtuell verlegen</small></div>\n  </div>\n  <div class=\"hdr-actions\">\n    <button class=\"chip-btn\" id=\"hdrSaved\">♡ <span class=\"hdr-label\">Meine Böden</span> <span class=\"count\" id=\"savedCount\">0</span></button>\n  </div>\n</header>\n\n<main>\n  <section>\n    <div class=\"stage-wrap\" id=\"stageWrap\">\n      <div class=\"stage\" id=\"stage\">\n        <canvas id=\"gl\"></canvas>\n        <div class=\"overlay\" id=\"overlay\">\n          <svg viewBox=\"0 0 1 1\" preserveAspectRatio=\"none\"><polygon id=\"quadPoly\" points=\"\" fill=\"rgba(181,122,62,.12)\" stroke=\"#fff\" stroke-width=\"2\" stroke-dasharray=\"6 5\" vector-effect=\"non-scaling-stroke\"/></svg>\n        </div>\n        <div class=\"split-line\" id=\"splitLine\"></div>\n        <span class=\"split-tag\" style=\"left:10px\">Vorher</span>\n        <span class=\"split-tag\" style=\"right:10px\">Nachher</span>\n        <div class=\"hint\" id=\"hint\">Ziehe die 4 Punkte auf die Ecken der Bodenfläche</div>\n      </div>\n      <div class=\"stage-tools\">\n        <button class=\"tool active\" id=\"tEdit\">⌖ Fläche anpassen</button>\n        <button class=\"tool\" id=\"tCompare\">◐ Vorher / Nachher</button>\n        <button class=\"tool\" id=\"tRotate\">↻ Richtung drehen</button>\n        <button class=\"tool primary\" id=\"tSave\">♡ Boden merken</button>\n      </div>\n      <div class=\"busy\" id=\"busy\"><div class=\"spinner\"></div><span id=\"busyText\">Boden wird verlegt …</span></div>\n    </div>\n  </section>\n\n  <aside class=\"panel\">\n    <nav class=\"steps\">\n      <button class=\"step active\" data-pane=\"room\"><span class=\"n\">1</span>Raum</button>\n      <button class=\"step\" data-pane=\"floor\"><span class=\"n\">2</span>Boden</button>\n      <button class=\"step\" data-pane=\"adjust\"><span class=\"n\">3</span>Anpassen</button>\n      <button class=\"step\" data-pane=\"mine\"><span class=\"n\">♡</span>Gemerkt</button>\n    </nav>\n\n    <div class=\"pane active\" id=\"pane-room\">\n      <h2>Raum wählen</h2>\n      <p class=\"lead\">Lade ein Foto deines Raums hoch oder starte mit unserem Beispielraum. Am besten funktioniert ein Foto mit freier, gut sichtbarer Bodenfläche.</p>\n      <button class=\"big-btn\" id=\"btnUpload\"><span class=\"ic\">📷</span><span><b>Foto hochladen</b><span>Aus der Galerie oder direkt mit der Kamera</span></span></button>\n      <input type=\"file\" id=\"file\" accept=\"image/*\" hidden>\n      <button class=\"big-btn solid\" id=\"btnDemo\"><span class=\"ic\">🛋️</span><span><b>Beispielraum verwenden</b><span>Wohnzimmer zum Ausprobieren</span></span></button>\n      <ul class=\"howto\">\n        <li><i>1</i>Foto wählen – möglichst gerade in den Raum fotografieren.</li>\n        <li><i>2</i>Die 4 Punkte auf die Ecken des Bodens ziehen (hinten links, hinten rechts, vorne rechts, vorne links).</li>\n        <li><i>3</i>Unter «Anpassen» die Raumgrösse eintragen – so stimmen Dielenbreite und Massstab.</li>\n      </ul>\n    </div>\n\n    <div class=\"pane\" id=\"pane-floor\">\n      <h2>Boden wählen</h2>\n      <p class=\"lead\">Probiere verschiedene Böden aus – hell oder dunkel, Landhausdiele oder Fischgrat. Ein Klick genügt für die Vorschau.</p>\n      <div class=\"filters\" id=\"filters\"></div>\n      <div class=\"tone\">Farbton:\n        <button class=\"filter active\" data-tone=\"all\">Alle</button>\n        <button class=\"filter\" data-tone=\"hell\">Hell</button>\n        <button class=\"filter\" data-tone=\"mittel\">Mittel</button>\n        <button class=\"filter\" data-tone=\"dunkel\">Dunkel</button>\n      </div>\n      <div class=\"grid\" id=\"catalog\"></div>\n    </div>\n\n    <div class=\"pane\" id=\"pane-adjust\">\n      <h2>Anpassen</h2>\n      <p class=\"lead\">Verlegerichtung, Raumgrösse und Lichtwirkung feinjustieren.</p>\n      <div class=\"field\">\n        <label class=\"t\">Verlegerichtung <output id=\"angOut\">0°</output></label>\n        <div class=\"seg\" id=\"angSeg\">\n          <button data-a=\"0\"><svg viewBox=\"0 0 24 24\"><g stroke=\"currentColor\" stroke-width=\"1.6\" fill=\"none\"><path d=\"M4 6h16M4 10h16M4 14h16M4 18h16\"/></g></svg>Quer</button>\n          <button data-a=\"90\"><svg viewBox=\"0 0 24 24\"><g stroke=\"currentColor\" stroke-width=\"1.6\" fill=\"none\"><path d=\"M6 4v16M10 4v16M14 4v16M18 4v16\"/></g></svg>Längs</button>\n          <button data-a=\"45\"><svg viewBox=\"0 0 24 24\"><g stroke=\"currentColor\" stroke-width=\"1.6\" fill=\"none\"><path d=\"M4 12L12 4M4 18L18 4M8 20L20 8M14 20l6-6\"/></g></svg>45°</button>\n          <button data-a=\"135\"><svg viewBox=\"0 0 24 24\"><g stroke=\"currentColor\" stroke-width=\"1.6\" fill=\"none\"><path d=\"M12 4l8 8M6 4l14 14M4 8l12 12M4 14l6 6\"/></g></svg>135°</button>\n        </div>\n        <input type=\"range\" id=\"ang\" min=\"0\" max=\"180\" step=\"1\" value=\"0\">\n      </div>\n      <div class=\"field\">\n        <label class=\"t\">Raumgrösse (sichtbare Bodenfläche)</label>\n        <div class=\"dims\">\n          <div><label for=\"w\">Breite in m</label><input class=\"inp\" type=\"number\" id=\"w\" min=\"0.5\" max=\"30\" step=\"0.1\" value=\"4.5\"></div>\n          <div><label for=\"d\">Tiefe in m</label><input class=\"inp\" type=\"number\" id=\"d\" min=\"0.5\" max=\"30\" step=\"0.1\" value=\"5\"></div>\n        </div>\n        <div class=\"area\">Fläche: <b id=\"areaOut\">22.5 m²</b> · bestimmt den Massstab der Dielen</div>\n      </div>\n      <div class=\"field\">\n        <label class=\"t\">Lichtwirkung <output id=\"lightOut\">60 %</output></label>\n        <input type=\"range\" id=\"light\" min=\"0\" max=\"100\" value=\"60\">\n        <div class=\"area\">Übernimmt Licht und Schatten aus deinem Foto.</div>\n      </div>\n      <div class=\"field\">\n        <label class=\"t\">Helligkeit <output id=\"brOut\">0</output></label>\n        <input type=\"range\" id=\"bright\" min=\"-30\" max=\"30\" value=\"0\">\n      </div>\n      <div class=\"toggle-row\"><span>Eckpunkte anzeigen</span><label class=\"switch\"><input type=\"checkbox\" id=\"swEdit\" checked><span></span></label></div>\n      <div class=\"toggle-row\"><span>Vorher / Nachher</span><label class=\"switch\"><input type=\"checkbox\" id=\"swCompare\"><span></span></label></div>\n      <div class=\"toggle-row\"><span>Boden einblenden</span><label class=\"switch\"><input type=\"checkbox\" id=\"swFloor\" checked><span></span></label></div>\n    </div>\n\n    <div class=\"pane\" id=\"pane-mine\">\n      <h2>Meine Böden</h2>\n      <p class=\"lead\">Deine gemerkten Böden. Bestelle Gratis-Muster, frage eine Offerte an oder teile die Vorschau.</p>\n      <div class=\"saved\" id=\"savedList\"></div>\n      <div class=\"cta-box\"><b>Beratung vom Profi</b>Naki GmbH in Muttenz verlegt Parkett, Vinyl und Kork in der ganzen Region Basel. <a href=\"https://nakigmbh.ch\" target=\"_blank\" rel=\"noopener\">nakigmbh.ch</a></div>\n    </div>\n  </aside>\n</main>\n<footer>Naki GmbH · Parkett &amp; Bodenbeläge · Muttenz BL · <a href=\"https://nakigmbh.ch\" target=\"_blank\" rel=\"noopener\">nakigmbh.ch</a><br>Farben und Strukturen sind Simulationen – für die echte Wirkung Muster bestellen.</footer>\n\n<div class=\"modal\" id=\"mRequest\">\n  <div class=\"dialog\">\n    <div class=\"dh\"><h3 id=\"reqTitle\">Gratis-Muster bestellen</h3><button class=\"x\" data-close>×</button></div>\n    <form id=\"reqForm\">\n      <div class=\"db\">\n        <div id=\"reqFloor\" class=\"tag\" style=\"font-size:12px\"></div>\n        <div class=\"row\">\n          <div><label>Vorname / Name *</label><input class=\"inp\" name=\"name\" required></div>\n          <div><label>Telefon</label><input class=\"inp\" name=\"tel\" type=\"tel\"></div>\n        </div>\n        <label>E-Mail *</label><input class=\"inp\" name=\"email\" type=\"email\" required>\n        <label>Strasse, Nr.</label><input class=\"inp\" name=\"street\">\n        <div class=\"row\">\n          <div><label>PLZ / Ort *</label><input class=\"inp\" name=\"city\" required placeholder=\"4132 Muttenz\"></div>\n          <div><label>Fläche ca. (m²)</label><input class=\"inp\" name=\"area\" type=\"number\" step=\"0.1\"></div>\n        </div>\n        <label>Nachricht</label><textarea class=\"inp\" name=\"msg\" rows=\"3\" placeholder=\"z. B. Altbelag entfernen, Treppe, Sockelleisten …\"></textarea>\n      </div>\n      <div class=\"df\"><button type=\"button\" class=\"btn\" data-close>Abbrechen</button><button class=\"btn pri\" type=\"submit\">Anfrage erstellen</button></div>\n    </form>\n  </div>\n</div>\n\n<div class=\"modal\" id=\"mSummary\">\n  <div class=\"dialog\">\n    <div class=\"dh\"><h3>Anfrage bereit</h3><button class=\"x\" data-close>×</button></div>\n    <div class=\"db\">\n      <p style=\"margin:0 0 10px;font-size:14px;line-height:1.5\">Kopiere den Text und sende ihn per E-Mail an <b id=\"mailShow\"></b> – oder öffne direkt dein Mailprogramm.</p>\n      <div class=\"summary\" id=\"sumText\"></div>\n      <p class=\"note\">Die Anfrage wird erst verschickt, wenn du die E-Mail selbst absendest.</p>\n    </div>\n    <div class=\"df\"><a class=\"btn\" id=\"mailLink\" href=\"#\" target=\"_blank\" rel=\"noopener\" style=\"text-decoration:none\">✉ Mail öffnen</a><button class=\"btn pri\" id=\"copySum\">Text kopieren</button></div>\n  </div>\n</div>\n\n<div class=\"modal\" id=\"mShare\">\n  <div class=\"dialog\">\n    <div class=\"dh\"><h3>Vorschau teilen</h3><button class=\"x\" data-close>×</button></div>\n    <div class=\"db\">\n      <img class=\"share-img\" id=\"shareImg\" alt=\"Bodenvorschau\">\n      <p style=\"margin:0;font-size:14px;line-height:1.5\">Bild gedrückt halten (Handy) oder Rechtsklick → «Bild speichern», dann per WhatsApp, Mail &amp; Co. teilen.</p>\n      <div class=\"summary\" id=\"shareText\" style=\"margin-top:10px\"></div>\n    </div>\n    <div class=\"df\"><button class=\"btn pri\" id=\"copyShare\">Beschreibung kopieren</button></div>\n  </div>\n</div>\n\n<div class=\"toast\" id=\"toast\"></div>\n\n<script>\n'use strict';\n/* ============ Konfiguration ============ */\nconst CONFIG = {\n  company: 'Naki GmbH',\n  email: 'info@nakigmbh.ch',        // ← Empfänger für Muster- und Offertanfragen anpassen\n  website: 'https://nakigmbh.ch',\n  texSize: 1024\n};\n\n/* ============ Native Bridge (iOS/Android-App) ============ */\nconst RN = window.ReactNativeWebView || null;\nfunction rnPost(o){ if(RN) RN.postMessage(JSON.stringify(o)); }\nif(RN) document.documentElement.classList.add('in-app');\n\n/* ============ Hilfsfunktionen ============ */\nconst $ = s => document.querySelector(s);\nconst $$ = s => [...document.querySelectorAll(s)];\nfunction toast(t){const el=$('#toast');el.textContent=t;el.classList.add('on');clearTimeout(toast._t);toast._t=setTimeout(()=>el.classList.remove('on'),2200)}\nconst store = {\n  get(k,def){try{const v=localStorage.getItem(k);return v?JSON.parse(v):def}catch(e){return def}},\n  set(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch(e){return false}}\n};\n\n/* ============ Rauschen (prozedurale Texturen) ============ */\nfunction hash2(x,y,s){let h=(x*374761393+y*668265263+s*982451653)|0;h=(h^(h>>>13))*1274126177|0;h=h^(h>>>16);return (h>>>0)/4294967295}\nfunction rng(seed){let s=seed>>>0||1;return()=>{s^=s<<13;s^=s>>>17;s^=s<<5;return((s>>>0)/4294967295)}}\nfunction vnoise(x,y,s){\n  const xi=Math.floor(x),yi=Math.floor(y),xf=x-xi,yf=y-yi;\n  const u=xf*xf*(3-2*xf),v=yf*yf*(3-2*yf);\n  const a=hash2(xi,yi,s),b=hash2(xi+1,yi,s),c=hash2(xi,yi+1,s),d=hash2(xi+1,yi+1,s);\n  return a+(b-a)*u+(c-a)*v+(a-b-c+d)*u*v;\n}\nfunction fbm(x,y,s,o){let t=0,a=.5,f=1,n=0;for(let i=0;i<o;i++){t+=a*vnoise(x*f,y*f,s+i*17);n+=a;a*=.5;f*=2.03}return t/n}\n\n/* ============ Produktkatalog ============ */\n// pattern: plank | herring | tile | cork ; Masse in Metern\nconst CATALOG = [\n  {id:'eiche-natur', name:'Eiche Natur', line:'Landhausdiele 1-Stab · gebürstet, geölt', cat:'Parkett', tone:'mittel', pattern:'plank', P:2.2, w:0.2, L:2.2, color:[184,134,86], var:.10, grain:.16, knots:.25},\n  {id:'eiche-hell', name:'Eiche Hell', line:'Landhausdiele · naturgeölt hell', cat:'Parkett', tone:'hell', pattern:'plank', P:2.2, w:0.2, L:2.2, color:[212,174,128], var:.08, grain:.13, knots:.15},\n  {id:'eiche-weiss', name:'Eiche Weiss', line:'Landhausdiele · weiss geölt', cat:'Parkett', tone:'hell', pattern:'plank', P:2.2, w:0.2, L:2.2, color:[226,211,188], var:.06, grain:.10, knots:.12},\n  {id:'eiche-rustikal', name:'Eiche Rustikal', line:'Landhausdiele · astig, gebürstet', cat:'Parkett', tone:'mittel', pattern:'plank', P:2.2, w:0.22, L:2.2, color:[170,118,72], var:.16, grain:.20, knots:1.4},\n  {id:'eiche-geraeuchert', name:'Eiche Geräuchert', line:'Landhausdiele · geräuchert, geölt', cat:'Parkett', tone:'dunkel', pattern:'plank', P:2.2, w:0.2, L:2.2, color:[112,76,48], var:.14, grain:.18, knots:.4},\n  {id:'nussbaum', name:'Amerik. Nussbaum', line:'Landhausdiele schmal · lackiert', cat:'Parkett', tone:'dunkel', pattern:'plank', P:2.1, w:0.15, L:2.1, color:[104,70,49], var:.18, grain:.20, knots:.1},\n  {id:'fischgrat-natur', name:'Fischgrat Eiche Natur', line:'Fischgratparkett 9 × 54 cm', cat:'Parkett', tone:'mittel', pattern:'herring', w:0.09, n:6, color:[192,146,96], var:.12, grain:.15, knots:.05},\n  {id:'fischgrat-grau', name:'Fischgrat Eiche Grau', line:'Fischgratparkett · grau geölt', cat:'Parkett', tone:'mittel', pattern:'herring', w:0.09, n:6, color:[156,146,134], var:.09, grain:.14, knots:.05},\n  {id:'fischgrat-dunkel', name:'Fischgrat Eiche Mocca', line:'Fischgratparkett · gebeizt', cat:'Parkett', tone:'dunkel', pattern:'herring', w:0.09, n:6, color:[96,66,44], var:.14, grain:.16, knots:.05},\n  {id:'schiffsboden-esche', name:'Schiffsboden Esche', line:'3-Stab-Optik · matt lackiert', cat:'Parkett', tone:'hell', pattern:'plank', P:2.1, w:0.14, L:0.7, color:[214,190,150], var:.12, grain:.14, knots:.05},\n  {id:'vinyl-holz-sand', name:'Vinyl Eiche Sand', line:'SPC-Vinyl Holzoptik · Klick', cat:'Vinyl', tone:'hell', pattern:'plank', P:2.4, w:0.23, L:1.2, color:[200,170,132], var:.07, grain:.10, knots:.3},\n  {id:'vinyl-holz-grau', name:'Vinyl Eiche Grau', line:'Dryback-Vinyl Holzoptik', cat:'Vinyl', tone:'mittel', pattern:'plank', P:2.4, w:0.2, L:1.2, color:[150,140,128], var:.08, grain:.12, knots:.3},\n  {id:'vinyl-stein-grau', name:'Vinyl Schiefer Grau', line:'SPC-Vinyl Steinoptik 60 × 60', cat:'Vinyl', tone:'dunkel', pattern:'tile', P:2.4, tw:0.6, th:0.6, color:[108,110,112], var:.08, stone:'slate'},\n  {id:'vinyl-beton', name:'Vinyl Beton Hellgrau', line:'SPC-Vinyl Betonoptik 60 × 120', cat:'Vinyl', tone:'hell', pattern:'tile', P:2.4, tw:1.2, th:0.6, color:[184,182,176], var:.05, stone:'concrete'},\n  {id:'vinyl-travertin', name:'Vinyl Travertin', line:'SPC-Vinyl Natursteinoptik', cat:'Vinyl', tone:'hell', pattern:'tile', P:2.4, tw:0.6, th:0.6, color:[214,198,172], var:.06, stone:'travertine'},\n  {id:'kork-natur', name:'Kork Natur', line:'Klick-Korkboden · geölt', cat:'Kork', tone:'mittel', pattern:'cork', P:1.8, tw:0.9, th:0.3, color:[184,140,94], var:.06},\n  {id:'kork-hell', name:'Kork Sand', line:'Klick-Korkboden · weiss pigmentiert', cat:'Kork', tone:'hell', pattern:'cork', P:1.8, tw:0.9, th:0.3, color:[214,190,156], var:.05},\n];\n\n/* ---------- Texturgenerierung ---------- */\nfunction periodOf(p){return p.pattern==='herring' ? 2*p.n*p.w : p.P}\n\nfunction genTexture(p, size){\n  const P = periodOf(p), px = P/size;           // Meter pro Pixel\n  const cv=document.createElement('canvas');cv.width=cv.height=size;\n  const ctx=cv.getContext('2d');const img=ctx.createImageData(size,size);const D=img.data;\n  const seedBase = [...p.id].reduce((a,c)=>a*31+c.charCodeAt(0)|0,7);\n  const gap = Math.max(0.0012, px*0.9);\n  // Vorab: Plankenreihen-Versatz\n  let rows=null;\n  if(p.pattern==='plank'){\n    const nRows=Math.round(P/p.w), per=Math.round(P/p.L); const r=rng(seedBase);\n    rows=[];for(let i=0;i<nRows;i++)rows.push(r()*P);\n    p._nRows=nRows;p._per=per;\n  }\n  const knotCache=new Map();\n  function knots(id){\n    if(knotCache.has(id))return knotCache.get(id);\n    const r=rng(id*7919+seedBase);const ks=[];\n    const cnt = r()<p.knots? (1+Math.floor(r()*p.knots*1.5)) : 0;\n    for(let i=0;i<cnt;i++)ks.push({u:r(),v:.2+r()*.6,r:.006+r()*.014});\n    knotCache.set(id,ks);return ks;\n  }\n  const [cr,cg,cb]=p.color;\n\n  function wood(id,u,v,L,W,edge){\n    // u entlang Faser (m), v quer (m)\n    const r=hash2(id,3,seedBase), r2=hash2(id,9,seedBase);\n    const tone = 1 + (r-.5)*2*p.var;\n    const ox=r*50, oy=r2*50;\n    const warp = fbm(u*0.9+ox, v*7+oy, seedBase, 3);\n    const lines = Math.sin((v*90 + warp*9 + Math.sin(u*0.7+ox)*1.2)*6.2831);\n    const grain = Math.pow(lines*.5+.5, 3);\n    const fine = vnoise(u*6+ox, v*520+oy, seedBase+3);\n    const ray = vnoise(u*30+ox, v*60+oy, seedBase+5);\n    let f = tone * (1 - p.grain*grain - .06*(fine-.5)*2 - .03*ray);\n    // Äste\n    if(p.knots>0){\n      const ks=knots(id);\n      for(const k of ks){\n        const du=(u/L-k.u)*L, dv=(v/W-k.v)*W;\n        const d=Math.sqrt(du*du*0.25+dv*dv);\n        if(d<k.r*3.5){\n          const ring = Math.sin(d*900)*.5+.5;\n          if(d<k.r) f*= .55+.15*ring; else f*= 1-.12*(1-(d-k.r)/(k.r*2.5))*ring;\n        }\n      }\n    }\n    // Fase/Fuge\n    if(edge<gap) f*=.55+.45*(edge/gap);\n    else if(edge<gap*2.5) f*=.94+.06*((edge-gap)/(gap*1.5));\n    return f;\n  }\n\n  for(let y=0;y<size;y++){\n    const Y=(y+.5)*px;\n    for(let x=0;x<size;x++){\n      const X=(x+.5)*px; let R,G,B;\n      if(p.pattern==='plank'){\n        const row=Math.floor(Y/p.w), v=Y-row*p.w;\n        const off=rows[row%rows.length];\n        let s=(X-off)%P; if(s<0)s+=P;\n        const col=Math.floor(s/p.L), u=s-col*p.L;\n        const id=row*101+col+1;\n        const edge=Math.min(v,p.w-v,u,p.L-u);\n        const f=wood(id,u,v,p.L,p.w,edge);\n        // leichte Farbverschiebung je Diele\n        const h=hash2(id,5,seedBase)-.5;\n        R=cr*f*(1+h*.05);G=cg*f;B=cb*f*(1-h*.06);\n      } else if(p.pattern==='herring'){\n        const n=p.n, w=p.w; const xu=X/w, yu=Y/w;\n        const a0=Math.floor((xu+yu)/2), b0=Math.floor((xu-yu)/(2*n));\n        let found=null;\n        for(let da=-n-1;da<=1&&!found;da++)for(let db=-1;db<=1&&!found;db++){\n          const a=a0+da,b=b0+db; const tx=a+b*n, ty=a-b*n; const lx=xu-tx, ly=yu-ty;\n          if(lx>=0&&lx<n&&ly>=0&&ly<1) found={t:0,u:lx,v:ly,a,b};\n          else if(lx>=0&&lx<1&&ly>=1&&ly<1+n) found={t:1,u:ly-1,v:lx,a,b};\n        }\n        if(!found){R=G=B=60}else{\n          // periodische Board-ID: Zentrum modulo Periode\n          const per=2*n;\n          const cxu = found.t===0 ? (found.a+found.b*n + n/2) : (found.a+found.b*n + .5);\n          const cyu = found.t===0 ? (found.a-found.b*n + .5) : (found.a-found.b*n + 1 + n/2);\n          const mx=((Math.round(cxu*2)%(per*2))+per*2)%(per*2), my=((Math.round(cyu*2)%(per*2))+per*2)%(per*2);\n          const id=mx*977+my*31+found.t*7+1;\n          const u=found.u*w, v=found.v*w, L=n*w;\n          const edge=Math.min(u,L-u,v,w-v);\n          const f=wood(id,u,v,L,w,edge);\n          const h=hash2(id,5,seedBase)-.5;\n          R=cr*f*(1+h*.05);G=cg*f;B=cb*f*(1-h*.06);\n        }\n      } else if(p.pattern==='tile'){\n        const row=Math.floor(Y/p.th); const shift = p.tw>p.th ? (row%2)*p.tw/2 : 0;\n        let s=(X-shift)%P; if(s<0)s+=P;\n        const col=Math.floor(s/p.tw); const u=s-col*p.tw, v=Y-row*p.th;\n        const id=row*53+col+1; const r=hash2(id,1,seedBase), r2=hash2(id,2,seedBase);\n        const edge=Math.min(u,p.tw-u,v,p.th-v);\n        const ox=r*80, oy=r2*80; let f;\n        if(p.stone==='slate'){\n          const m=fbm(u*3+ox,v*3+oy,seedBase,4), st=fbm(u*1.5+ox,v*14+oy,seedBase+4,3), sp=vnoise(u*300+ox,v*300+oy,seedBase+9);\n          f=(1+(r-.5)*2*p.var)*(.82+.3*m+.12*(st-.5)+.05*(sp-.5));\n        } else if(p.stone==='concrete'){\n          const m=fbm(u*2+ox,v*2+oy,seedBase,5), sp=vnoise(u*260+ox,v*260+oy,seedBase+9);\n          const pit = vnoise(u*90+ox,v*90+oy,seedBase+11)>.86 ? .9 : 1;\n          f=(1+(r-.5)*2*p.var)*(.88+.22*m+.05*(sp-.5))*pit;\n        } else {\n          const m=fbm(u*2+ox,v*5+oy,seedBase,4), band=Math.sin((v*18+m*4)*6.28)*.5+.5;\n          const pit = fbm(u*40+ox,v*25+oy,seedBase+11,2)>.72 ? .86 : 1;\n          f=(1+(r-.5)*2*p.var)*(.9+.12*m+.06*band)*pit;\n        }\n        const g=0.0025;\n        if(edge<g){R=168;G=164;B=156; if(p.stone==='slate'){R=82;G=82;B=82}}\n        else { if(edge<g*2) f*=.92; R=cr*f;G=cg*f;B=cb*f; }\n      } else { // cork\n        const row=Math.floor(Y/p.th); const shift=(row%2)*p.tw/2;\n        let s=(X-shift)%P; if(s<0)s+=P; const col=Math.floor(s/p.tw);\n        const u=s-col*p.tw, v=Y-row*p.th; const id=row*53+col+1; const r=hash2(id,1,seedBase);\n        const edge=Math.min(u,p.tw-u,v,p.th-v);\n        const g1=vnoise(X*420,Y*420,seedBase), g2=vnoise(X*150,Y*150,seedBase+2), g3=vnoise(X*900,Y*900,seedBase+4);\n        let f=(1+(r-.5)*2*p.var)*(.78+.28*g1+.18*(g2-.5)+.1*(g3-.5));\n        if(g1>.82) f*=.72;\n        if(edge<0.0015) f*=.6;\n        R=cr*f;G=cg*f*.98;B=cb*f*.95;\n      }\n      const i=(y*size+x)*4;\n      D[i]=R<0?0:R>255?255:R; D[i+1]=G<0?0:G>255?255:G; D[i+2]=B<0?0:B>255?255:B; D[i+3]=255;\n    }\n  }\n  ctx.putImageData(img,0,0);\n  return cv;\n}\n\n/* ============ Beispielraum ============ */\nfunction demoRoom(){\n  const W=1600,H=1050, c=document.createElement('canvas');c.width=W;c.height=H;const x=c.getContext('2d');\n  const bl=[360,640], br=[1240,640], tl=[360,110], tr=[1240,110];\n  // Decke\n  let g=x.createLinearGradient(0,0,0,110);g.addColorStop(0,'#e9e4dc');g.addColorStop(1,'#f4f0ea');\n  x.fillStyle=g;x.beginPath();x.moveTo(0,0);x.lineTo(W,0);x.lineTo(...tr);x.lineTo(...tl);x.fill();\n  // Rückwand\n  g=x.createLinearGradient(360,0,1240,0);g.addColorStop(0,'#ece5da');g.addColorStop(.5,'#f3eee6');g.addColorStop(1,'#e8e0d4');\n  x.fillStyle=g;x.fillRect(360,110,880,530);\n  // Seitenwände\n  g=x.createLinearGradient(0,0,360,0);g.addColorStop(0,'#d9d0c3');g.addColorStop(1,'#e6ddd0');\n  x.fillStyle=g;x.beginPath();x.moveTo(0,0);x.lineTo(...tl);x.lineTo(...bl);x.lineTo(0,H);x.fill();\n  g=x.createLinearGradient(1240,0,W,0);g.addColorStop(0,'#e3dacd');g.addColorStop(1,'#d2c8ba');\n  x.fillStyle=g;x.beginPath();x.moveTo(W,0);x.lineTo(...tr);x.lineTo(...br);x.lineTo(W,H);x.fill();\n  // Fenster Rückwand\n  x.fillStyle='#fff';x.fillRect(520,170,560,380);\n  g=x.createLinearGradient(0,180,0,540);g.addColorStop(0,'#cfe2ee');g.addColorStop(1,'#eef4f6');\n  x.fillStyle=g;x.fillRect(534,184,532,352);\n  x.fillStyle='#9fb79a';x.beginPath();x.moveTo(534,470);for(let i=0;i<=532;i+=20)x.lineTo(534+i,450+Math.sin(i*.05)*14+Math.cos(i*.13)*8);x.lineTo(1066,536);x.lineTo(534,536);x.fill();\n  x.fillStyle='#fff';x.fillRect(795,184,10,352);x.fillRect(534,355,532,8);\n  // Vorhänge\n  x.fillStyle='rgba(235,225,210,.95)';x.fillRect(470,150,60,490);x.fillRect(1070,150,60,490);\n  x.strokeStyle='rgba(0,0,0,.06)';x.lineWidth=2;for(let i=0;i<5;i++){x.beginPath();x.moveTo(482+i*11,150);x.lineTo(482+i*11,640);x.stroke();x.beginPath();x.moveTo(1082+i*11,150);x.lineTo(1082+i*11,640);x.stroke()}\n  // Bild links\n  x.fillStyle='#fff';x.beginPath();x.moveTo(120,300);x.lineTo(260,315);x.lineTo(260,480);x.lineTo(120,500);x.fill();\n  x.fillStyle='#c98f5a';x.beginPath();x.moveTo(132,312);x.lineTo(248,325);x.lineTo(248,470);x.lineTo(132,488);x.fill();\n  x.fillStyle='#e7c89c';x.beginPath();x.arc(190,400,30,0,7);x.fill();\n  // Boden (grau, wird ersetzt) mit Licht\n  x.fillStyle='#8d8a85';x.beginPath();x.moveTo(...bl);x.lineTo(...br);x.lineTo(W,H);x.lineTo(0,H);x.fill();\n  // Lichtfleck vom Fenster\n  x.save();x.beginPath();x.moveTo(...bl);x.lineTo(...br);x.lineTo(W,H);x.lineTo(0,H);x.clip();\n  g=x.createRadialGradient(800,780,40,800,760,620);g.addColorStop(0,'rgba(255,250,240,.55)');g.addColorStop(1,'rgba(255,250,240,0)');\n  x.fillStyle=g;x.fillRect(0,600,W,H);\n  g=x.createLinearGradient(0,640,0,H);g.addColorStop(0,'rgba(0,0,0,.12)');g.addColorStop(.25,'rgba(0,0,0,0)');g.addColorStop(1,'rgba(0,0,0,.18)');\n  x.fillStyle=g;x.fillRect(0,600,W,H);\n  g=x.createLinearGradient(0,0,W,0);g.addColorStop(0,'rgba(0,0,0,.18)');g.addColorStop(.3,'rgba(0,0,0,0)');g.addColorStop(.7,'rgba(0,0,0,0)');g.addColorStop(1,'rgba(0,0,0,.14)');\n  x.fillStyle=g;x.fillRect(0,600,W,H);x.restore();\n  // Sockelleisten\n  x.fillStyle='#fbfaf7';x.fillRect(360,628,880,12);\n  x.beginPath();x.moveTo(0,H-24);x.lineTo(...[360,628]);x.lineTo(360,640);x.lineTo(0,H);x.fill();\n  x.beginPath();x.moveTo(W,H-24);x.lineTo(1240,628);x.lineTo(1240,640);x.lineTo(W,H);x.fill();\n  // Pflanze rechts\n  x.fillStyle='#d9cbb6';x.fillRect(1300,560,70,90);x.fillStyle='#c4b49c';x.fillRect(1300,560,70,10);\n  x.fillStyle='#5f7f55';for(let i=0;i<14;i++){x.save();x.translate(1335,565);x.rotate(-1.4+i*.2);x.beginPath();x.ellipse(0,-60,12,58,0,0,7);x.fill();x.restore()}\n  return {canvas:c, quad:[[360/W,640/H],[1240/W,640/H],[1,1],[0,1]], dims:[4.5,5]};\n}\n\n/* ============ WebGL Renderer ============ */\nconst glc=$('#gl');\nconst gl=glc.getContext('webgl2',{preserveDrawingBuffer:true,antialias:true,premultipliedAlpha:false});\nconst state = {\n  product: CATALOG[0], angle:0, W:4.5, D:5, light:.6, bright:0, showFloor:true, split:-1,\n  quad:null, photo:null, avgLum:.5, filter:'Alle', tone:'all', editing:true\n};\nlet prog, uni={}, texPhoto, texFloor, aniso;\nconst texCache=new Map();\n\nfunction initGL(){\n  if(!gl){$('#stage').innerHTML='<div class=\"nogl\">Dein Browser unterstützt WebGL 2 nicht.<br>Bitte öffne den Bodenplaner in einem aktuellen Chrome, Safari, Edge oder Firefox.</div>';return false}\n  const vs=`#version 300 es\n  in vec2 a; out vec2 vP;\n  void main(){ vP=vec2(a.x*.5+.5, .5-a.y*.5); gl_Position=vec4(a,0.,1.); }`;\n  const fs=`#version 300 es\n  precision highp float;\n  in vec2 vP; out vec4 o;\n  uniform sampler2D uPhoto, uFloor;\n  uniform mat3 uHinv; uniform vec2 uRoom; uniform float uAngle,uTexScale,uLight,uAvgLum,uSplit,uShow,uBright;\n  void main(){\n    vec4 ph=texture(uPhoto,vP);\n    vec3 q=uHinv*vec3(vP,1.);\n    vec2 uv=q.xy/q.z;\n    vec2 m=uv*uRoom;\n    float c=cos(uAngle), s=sin(uAngle);\n    vec2 t=vec2(c*m.x-s*m.y, s*m.x+c*m.y)*uTexScale;\n    vec3 fl=texture(uFloor,t).rgb;\n    float lum=dot(ph.rgb,vec3(.299,.587,.114));\n    float sh=clamp(lum/max(uAvgLum,.02),.3,1.9);\n    fl*=mix(1.,sh,uLight);\n    fl+=max(lum-uAvgLum*1.25,0.)*uLight*.35;\n    fl*=1.+uBright;\n    vec2 d=min(uv,1.-uv); float e=min(d.x,d.y);\n    float aa=clamp(e/max(fwidth(e),1e-5)+.5,0.,1.);\n    if(q.z<=0.) aa=0.;\n    aa*=uShow*step(uSplit,vP.x);\n    o=vec4(mix(ph.rgb,clamp(fl,0.,1.),aa),1.);\n  }`;\n  const sh=(t,src)=>{const s=gl.createShader(t);gl.shaderSource(s,src);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw gl.getShaderInfoLog(s);return s};\n  prog=gl.createProgram();gl.attachShader(prog,sh(gl.VERTEX_SHADER,vs));gl.attachShader(prog,sh(gl.FRAGMENT_SHADER,fs));gl.linkProgram(prog);gl.useProgram(prog);\n  const buf=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buf);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,1,-1,-1,1,1,1]),gl.STATIC_DRAW);\n  const loc=gl.getAttribLocation(prog,'a');gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,2,gl.FLOAT,false,0,0);\n  ['uPhoto','uFloor','uHinv','uRoom','uAngle','uTexScale','uLight','uAvgLum','uSplit','uShow','uBright'].forEach(n=>uni[n]=gl.getUniformLocation(prog,n));\n  gl.uniform1i(uni.uPhoto,0);gl.uniform1i(uni.uFloor,1);\n  aniso=gl.getExtension('EXT_texture_filter_anisotropic');\n  texPhoto=gl.createTexture();texFloor=gl.createTexture();\n  return true;\n}\nfunction uploadPhoto(cv){\n  gl.activeTexture(gl.TEXTURE0);gl.bindTexture(gl.TEXTURE_2D,texPhoto);\n  gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,cv);\n  gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);\n  gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);\n}\nfunction uploadFloor(cv){\n  gl.activeTexture(gl.TEXTURE1);gl.bindTexture(gl.TEXTURE_2D,texFloor);\n  gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,cv);\n  gl.generateMipmap(gl.TEXTURE_2D);\n  gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR_MIPMAP_LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);\n  gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.REPEAT);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.REPEAT);\n  if(aniso)gl.texParameterf(gl.TEXTURE_2D,aniso.TEXTURE_MAX_ANISOTROPY_EXT,Math.min(16,gl.getParameter(aniso.MAX_TEXTURE_MAX_ANISOTROPY_EXT)));\n}\n\n/* Homographie Einheitsquadrat → Viereck */\nfunction homography(q){\n  const [[x0,y0],[x1,y1],[x2,y2],[x3,y3]]=q;\n  const sx=x0-x1+x2-x3, sy=y0-y1+y2-y3;\n  let g=0,h=0;\n  if(Math.abs(sx)>1e-9||Math.abs(sy)>1e-9){\n    const dx1=x1-x2,dx2=x3-x2,dy1=y1-y2,dy2=y3-y2, den=dx1*dy2-dx2*dy1;\n    if(Math.abs(den)>1e-12){g=(sx*dy2-dx2*sy)/den;h=(dx1*sy-sx*dy1)/den}\n  }\n  return [x1-x0+g*x1, x3-x0+h*x3, x0, y1-y0+g*y1, y3-y0+h*y3, y0, g, h, 1];\n}\nfunction inv3(m){\n  const [a,b,c,d,e,f,g,h,i]=m; const A=e*i-f*h,B=-(d*i-f*g),C=d*h-e*g; const det=a*A+b*B+c*C||1e-12;\n  return [A/det,-(b*i-c*h)/det,(b*f-c*e)/det, B/det,(a*i-c*g)/det,-(a*f-c*d)/det, C/det,-(a*h-b*g)/det,(a*e-b*d)/det];\n}\nfunction mapH(H,u,v){const w=H[6]*u+H[7]*v+H[8];return[(H[0]*u+H[1]*v+H[2])/w,(H[3]*u+H[4]*v+H[5])/w]}\n\nlet lumCanvas=null, lumData=null;\nfunction prepLum(cv){\n  const s=Math.min(1,240/cv.width);lumCanvas=document.createElement('canvas');lumCanvas.width=Math.round(cv.width*s);lumCanvas.height=Math.round(cv.height*s);\n  const x=lumCanvas.getContext('2d');x.drawImage(cv,0,0,lumCanvas.width,lumCanvas.height);lumData=x.getImageData(0,0,lumCanvas.width,lumCanvas.height).data;\n}\nfunction computeAvgLum(){\n  if(!lumData)return;const H=homography(state.quad);let t=0,n=0;const W=lumCanvas.width,Hh=lumCanvas.height;\n  for(let i=0;i<24;i++)for(let j=0;j<24;j++){\n    const [x,y]=mapH(H,(i+.5)/24,(j+.5)/24);const px=Math.min(W-1,Math.max(0,Math.floor(x*W))),py=Math.min(Hh-1,Math.max(0,Math.floor(y*Hh)));\n    const k=(py*W+px)*4;t+=(lumData[k]*.299+lumData[k+1]*.587+lumData[k+2]*.114)/255;n++;\n  }\n  state.avgLum=Math.max(.03,t/n);\n}\n\nlet raf=0;\nfunction render(){ if(raf)return; raf=requestAnimationFrame(()=>{raf=0;draw()}) }\nfunction draw(){\n  if(!gl||!state.photo)return;\n  gl.viewport(0,0,glc.width,glc.height);\n  const Hinv=inv3(homography(state.quad));\n  gl.uniformMatrix3fv(uni.uHinv,true,new Float32Array(Hinv));\n  gl.uniform2f(uni.uRoom,state.W,state.D);\n  gl.uniform1f(uni.uAngle,state.angle*Math.PI/180);\n  gl.uniform1f(uni.uTexScale,1/periodOf(state.product));\n  gl.uniform1f(uni.uLight,state.light);\n  gl.uniform1f(uni.uAvgLum,state.avgLum);\n  gl.uniform1f(uni.uSplit,state.split);\n  gl.uniform1f(uni.uShow,state.showFloor?1:0);\n  gl.uniform1f(uni.uBright,state.bright);\n  gl.drawArrays(gl.TRIANGLE_STRIP,0,4);\n}\n\n/* ============ Raum laden ============ */\nfunction setPhoto(cv,quad,dims){\n  state.photo=cv; glc.width=cv.width; glc.height=cv.height;\n  uploadPhoto(cv); prepLum(cv);\n  state.quad=quad.map(p=>p.slice());\n  if(dims){state.W=dims[0];state.D=dims[1];$('#w').value=dims[0];$('#d').value=dims[1];updArea()}\n  computeAvgLum(); layoutStage(); placeHandles(); render();\n}\nfunction layoutStage(){\n  if(!state.photo)return;const ar=state.photo.width/state.photo.height;\n  const maxH=window.innerWidth<960? window.innerHeight*.55 : window.innerHeight-190;\n  $('#stage').style.width=`min(100%, ${Math.round(maxH*ar)}px)`;\n}\nwindow.addEventListener('resize',layoutStage);\n\n$('#btnUpload').onclick=()=>{ if(RN) rnPost({type:'pick'}); else $('#file').click(); };\n$('#file').onchange=e=>{\n  const f=e.target.files[0];if(!f)return;loadImageSrc(URL.createObjectURL(f),true);e.target.value='';\n};\nwindow.nakiLoadImage=src=>loadImageSrc(src,false);\nfunction loadImageSrc(url,revoke){\n  const im=new Image();\n  im.onload=()=>{\n    const s=Math.min(1,1800/Math.max(im.width,im.height));const c=document.createElement('canvas');c.width=Math.round(im.width*s);c.height=Math.round(im.height*s);\n    c.getContext('2d').drawImage(im,0,0,c.width,c.height);if(revoke)URL.revokeObjectURL(url);isDemo=false;\n    setPhoto(c,[[.25,.55],[.75,.55],[.95,.97],[.05,.97]]);\n    setEditing(true); showHint('Ziehe die 4 Punkte auf die Ecken der Bodenfläche',5000); toast('Foto geladen');\n    if(window.innerWidth<960)$('#stageWrap').scrollIntoView({behavior:'smooth'});\n  };\n  im.onerror=()=>toast('Bild konnte nicht gelesen werden');im.src=url;\n}\n$('#btnDemo').onclick=()=>{isDemo=true;const d=demoRoom();setPhoto(d.canvas,d.quad,d.dims);toast('Beispielraum geladen')};\n\n/* ============ Eckpunkte ============ */\nconst handles=[];const labels=['1','2','3','4'];\nfunction buildHandles(){\n  const ov=$('#overlay');\n  for(let i=0;i<4;i++){\n    const h=document.createElement('div');h.className='handle';h.textContent=labels[i];h.title=['Hinten links','Hinten rechts','Vorne rechts','Vorne links'][i];\n    ov.appendChild(h);handles.push(h);\n    h.addEventListener('pointerdown',ev=>{\n      ev.preventDefault();h.setPointerCapture(ev.pointerId);\n      const r=$('#stage').getBoundingClientRect();\n      const mv=e=>{state.quad[i]=[Math.min(1,Math.max(0,(e.clientX-r.left)/r.width)),Math.min(1,Math.max(0,(e.clientY-r.top)/r.height))];placeHandles();render()};\n      const up=()=>{h.removeEventListener('pointermove',mv);h.removeEventListener('pointerup',up);h.removeEventListener('pointercancel',up);computeAvgLum();render()};\n      h.addEventListener('pointermove',mv);h.addEventListener('pointerup',up);h.addEventListener('pointercancel',up);\n    });\n  }\n}\nfunction placeHandles(){\n  state.quad.forEach((p,i)=>{handles[i].style.left=p[0]*100+'%';handles[i].style.top=p[1]*100+'%'});\n  $('#quadPoly').setAttribute('points',state.quad.map(p=>p.join(',')).join(' '));\n}\nfunction setEditing(on){state.editing=on;$('#overlay').classList.toggle('hidden',!on);$('#tEdit').classList.toggle('active',on);$('#swEdit').checked=on}\n$('#tEdit').onclick=()=>setEditing(!state.editing);\n$('#swEdit').onchange=e=>setEditing(e.target.checked);\n\n/* Vorher/Nachher */\nfunction setCompare(on){\n  state.split=on?.5:-1;$('#splitLine').classList.toggle('on',on);$('#stage').classList.toggle('split-on',on);\n  $('#splitLine').style.left='50%';$('#tCompare').classList.toggle('active',on);$('#swCompare').checked=on;if(on)setEditing(false);render();\n}\n$('#tCompare').onclick=()=>setCompare(state.split<0);\n$('#swCompare').onchange=e=>setCompare(e.target.checked);\n(()=>{const sl=$('#splitLine');sl.addEventListener('pointerdown',ev=>{ev.preventDefault();sl.setPointerCapture(ev.pointerId);const r=$('#stage').getBoundingClientRect();\n  const mv=e=>{const v=Math.min(1,Math.max(0,(e.clientX-r.left)/r.width));state.split=v;sl.style.left=v*100+'%';render()};\n  const up=()=>{sl.removeEventListener('pointermove',mv);sl.removeEventListener('pointerup',up)};sl.addEventListener('pointermove',mv);sl.addEventListener('pointerup',up)})})();\n\nfunction showHint(t,ms){const h=$('#hint');h.textContent=t;h.style.opacity=1;clearTimeout(showHint._t);showHint._t=setTimeout(()=>h.style.opacity=0,ms||3500)}\n\n/* ============ Katalog ============ */\nconst cats=['Alle','Parkett','Vinyl','Kork'];\nfunction buildFilters(){\n  const f=$('#filters');f.innerHTML='';\n  cats.forEach(c=>{const b=document.createElement('button');b.className='filter'+(c===state.filter?' active':'');b.textContent=c;b.onclick=()=>{state.filter=c;buildFilters();buildCatalog()};f.appendChild(b)});\n}\n$$('[data-tone]').forEach(b=>b.onclick=()=>{state.tone=b.dataset.tone;$$('[data-tone]').forEach(x=>x.classList.toggle('active',x===b));buildCatalog()});\nconst swatchCache=new Map();\nfunction swatch(p){\n  if(swatchCache.has(p.id))return swatchCache.get(p.id);\n  const P=periodOf(p);const t=genTexture(p,192); // eine Periode\n  // Ausschnitt ca. 1.1 m breit\n  const c=document.createElement('canvas');c.width=240;c.height=180;const x=c.getContext('2d');\n  const span=Math.min(1.1,P), sc=240/(span/P*192);\n  x.imageSmoothingQuality='high';\n  for(let yy=0;yy<180;yy+=192*sc)for(let xx=0;xx<240;xx+=192*sc)x.drawImage(t,xx,yy,192*sc,192*sc);\n  swatchCache.set(p.id,c);return c;\n}\nfunction buildCatalog(){\n  const g=$('#catalog');g.innerHTML='';\n  CATALOG.filter(p=>(state.filter==='Alle'||p.cat===state.filter)&&(state.tone==='all'||p.tone===state.tone)).forEach(p=>{\n    const b=document.createElement('button');b.className='card'+(p.id===state.product.id?' active':'');\n    const cv=document.createElement('canvas');cv.width=240;cv.height=180;b.appendChild(cv);\n    const m=document.createElement('div');m.className='meta';m.innerHTML=`<span class=\"tag\">${p.cat}</span><b>${p.name}</b><span>${p.line}</span>`;b.appendChild(m);\n    b.onclick=()=>{selectProduct(p);$$('#catalog .card').forEach(x=>x.classList.remove('active'));b.classList.add('active')};\n    g.appendChild(b);\n    requestIdleCallbackSafe(()=>cv.getContext('2d').drawImage(swatch(p),0,0));\n  });\n  if(!g.children.length)g.innerHTML='<div class=\"empty\" style=\"grid-column:1/-1\">Keine Böden in dieser Auswahl.</div>';\n}\nfunction requestIdleCallbackSafe(fn){(window.requestIdleCallback||((f)=>setTimeout(f,16)))(fn)}\n\nfunction selectProduct(p,silent){\n  state.product=p;\n  if(texCache.has(p.id)){uploadFloor(texCache.get(p.id));render();if(!silent)showHint(p.name+' · '+p.line,2200);return Promise.resolve()}\n  $('#busy').classList.add('on');\n  return new Promise(res=>setTimeout(()=>{\n    const t=genTexture(p,CONFIG.texSize);texCache.set(p.id,t);uploadFloor(t);\n    $('#busy').classList.remove('on');render();if(!silent)showHint(p.name+' · '+p.line,2200);res();\n  },30));\n}\n\n/* ============ Anpassen ============ */\nfunction setAngle(a){state.angle=((a%180)+180)%180;$('#ang').value=state.angle;$('#angOut').textContent=Math.round(state.angle)+'°';\n  $$('#angSeg button').forEach(b=>b.classList.toggle('active',+b.dataset.a===Math.round(state.angle)));render()}\n$$('#angSeg button').forEach(b=>b.onclick=()=>setAngle(+b.dataset.a));\n$('#ang').oninput=e=>setAngle(+e.target.value);\n$('#tRotate').onclick=()=>{const order=[0,90,45,135];const i=order.indexOf(Math.round(state.angle));setAngle(order[(i+1)%4]);showHint('Verlegerichtung: '+Math.round(state.angle)+'°',1500)};\nfunction updArea(){$('#areaOut').textContent=(state.W*state.D).toFixed(1).replace(/\\.0$/,'')+' m²'}\n$('#w').oninput=e=>{const v=parseFloat(e.target.value);if(v>0){state.W=v;updArea();render()}};\n$('#d').oninput=e=>{const v=parseFloat(e.target.value);if(v>0){state.D=v;updArea();render()}};\n$('#light').oninput=e=>{state.light=e.target.value/100;$('#lightOut').textContent=e.target.value+' %';render()};\n$('#bright').oninput=e=>{state.bright=e.target.value/100;$('#brOut').textContent=(e.target.value>0?'+':'')+e.target.value;render()};\n$('#swFloor').onchange=e=>{state.showFloor=e.target.checked;render()};\n\n/* ============ Tabs ============ */\nfunction showPane(id){$$('.step').forEach(s=>s.classList.toggle('active',s.dataset.pane===id));$$('.pane').forEach(p=>p.classList.toggle('active',p.id==='pane-'+id));if(id==='mine')renderSaved()}\n$$('.step').forEach(s=>s.onclick=()=>showPane(s.dataset.pane));\n$('#hdrSaved').onclick=()=>{showPane('mine');if(window.innerWidth<960)$('.panel').scrollIntoView({behavior:'smooth'})};\n\n/* ============ Meine Böden ============ */\nfunction snapshot(maxW){\n  draw();const s=Math.min(1,maxW/glc.width);const c=document.createElement('canvas');c.width=Math.round(glc.width*s);c.height=Math.round(glc.height*s);\n  c.getContext('2d').drawImage(glc,0,0,c.width,c.height);return c;\n}\nfunction getSaved(){return store.get('naki-boeden',[])}\nfunction updCount(){$('#savedCount').textContent=getSaved().length}\n$('#tSave').onclick=()=>{\n  const list=getSaved();\n  const wasSplit=state.split;state.split=-1;\n  const thumb=snapshot(640).toDataURL('image/jpeg',.82);\n  state.split=wasSplit;render();\n  const ps=Math.min(1,1100/Math.max(state.photo.width,state.photo.height));const pc=document.createElement('canvas');pc.width=Math.round(state.photo.width*ps);pc.height=Math.round(state.photo.height*ps);pc.getContext('2d').drawImage(state.photo,0,0,pc.width,pc.height);\n  const item={id:Date.now(),product:state.product.id,angle:state.angle,W:state.W,D:state.D,light:state.light,bright:state.bright,quad:state.quad,thumb,photo:isDemo?null:pc.toDataURL('image/jpeg',.78),demo:isDemo,date:new Date().toISOString()};\n  list.unshift(item);\n  if(!store.set('naki-boeden',list)){item.photo=null;if(!store.set('naki-boeden',list)){list.shift();toast('Speicher voll – bitte alte Einträge löschen');return}}\n  updCount();toast('♡ '+state.product.name+' gemerkt');\n};\nfunction prodById(id){return CATALOG.find(p=>p.id===id)||CATALOG[0]}\nfunction renderSaved(){\n  const list=getSaved(), el=$('#savedList');el.innerHTML='';\n  if(!list.length){el.innerHTML='<div class=\"empty\"><div class=\"e-ic\">♡</div>Noch keine Böden gemerkt.<br>Wähle einen Boden und tippe auf «Boden merken».</div>';return}\n  list.forEach(it=>{\n    const p=prodById(it.product);const d=new Date(it.date);\n    const box=document.createElement('div');box.className='saved-item';\n    box.innerHTML=`<img alt=\"\" src=\"${it.thumb}\"><div class=\"meta\"><b>${p.name}</b><small>${p.line} · ${Math.round(it.angle)}° · ${(it.W*it.D).toFixed(1)} m² · ${d.toLocaleDateString('de-CH')}</small></div>\n    <div class=\"acts\"><button class=\"mini\" data-act=\"load\">Weiter verlegen</button><button class=\"mini pri\" data-act=\"sample\">Gratis-Muster</button><button class=\"mini\" data-act=\"offer\">Offerte</button><button class=\"mini\" data-act=\"share\">Teilen</button><button class=\"mini del\" data-act=\"del\">Löschen</button></div>`;\n    box.querySelector('[data-act=load]').onclick=()=>loadSaved(it);\n    box.querySelector('[data-act=sample]').onclick=()=>openRequest('sample',it);\n    box.querySelector('[data-act=offer]').onclick=()=>openRequest('offer',it);\n    box.querySelector('[data-act=share]').onclick=()=>openShare(it.thumb,p,it);\n    box.querySelector('[data-act=del]').onclick=()=>{store.set('naki-boeden',getSaved().filter(x=>x.id!==it.id));updCount();renderSaved()};\n    el.appendChild(box);\n  });\n}\nfunction loadSaved(it){\n  const apply=(cv)=>{\n    setPhoto(cv,it.quad,[it.W,it.D]);state.light=it.light;$('#light').value=Math.round(it.light*100);$('#lightOut').textContent=Math.round(it.light*100)+' %';\n    state.bright=it.bright||0;$('#bright').value=Math.round(state.bright*100);setAngle(it.angle);\n    selectProduct(prodById(it.product)).then(()=>{buildCatalog()});toast('Konfiguration geladen');\n    if(window.innerWidth<960)$('#stageWrap').scrollIntoView({behavior:'smooth'});\n  };\n  if(it.demo||!it.photo){isDemo=true;apply(demoRoom().canvas);if(!it.demo)toast('Foto nicht gespeichert – Beispielraum geladen')}\n  else{const im=new Image();im.onload=()=>{isDemo=false;const c=document.createElement('canvas');c.width=im.width;c.height=im.height;c.getContext('2d').drawImage(im,0,0);apply(c)};im.src=it.photo}\n}\n\n/* ============ Anfrage (Muster / Offerte) ============ */\nlet reqCtx=null;\nfunction openRequest(kind,it){\n  reqCtx={kind,it};const p=prodById(it.product);\n  $('#reqTitle').textContent=kind==='sample'?'Gratis-Muster bestellen':'Offerte anfragen';\n  $('#reqFloor').textContent=p.name+' · '+p.line;\n  const f=$('#reqForm');const saved=store.get('naki-kontakt',{});\n  ['name','tel','email','street','city'].forEach(k=>{if(saved[k]&&!f[k].value)f[k].value=saved[k]});\n  f.area.value=(it.W*it.D).toFixed(1);\n  $('#mRequest').classList.add('on');\n}\n$('#reqForm').addEventListener('submit',e=>{\n  e.preventDefault();const f=e.target;const v=k=>f[k].value.trim();\n  store.set('naki-kontakt',{name:v('name'),tel:v('tel'),email:v('email'),street:v('street'),city:v('city')});\n  const p=prodById(reqCtx.it.product);const isS=reqCtx.kind==='sample';\n  const subject=(isS?'Musterbestellung: ':'Offertanfrage: ')+p.name;\n  const body=`Guten Tag\n\n${isS?'Gerne bestelle ich ein Gratis-Muster für folgenden Boden:':'Gerne möchte ich eine Offerte für folgenden Boden:'}\n\nBoden: ${p.name} (${p.line})\nKategorie: ${p.cat}\nVerlegerichtung: ${Math.round(reqCtx.it.angle)}°\nFläche ca.: ${v('area')||'-'} m²\n\nName: ${v('name')}\nAdresse: ${v('street')||'-'}, ${v('city')}\nE-Mail: ${v('email')}\nTelefon: ${v('tel')||'-'}\n${v('msg')?'\\nNachricht:\\n'+v('msg')+'\\n':''}\nFreundliche Grüsse\n${v('name')}\n\n(erstellt mit dem Naki Bodenplaner)`;\n  $('#sumText').textContent=body;$('#mailShow').textContent=CONFIG.email;\n  $('#mailLink').href=`mailto:${CONFIG.email}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;\n  $('#mRequest').classList.remove('on');$('#mSummary').classList.add('on');\n});\nasync function copy(t){if(RN){rnPost({type:'copy',text:t});toast('In die Zwischenablage kopiert');return}try{await navigator.clipboard.writeText(t);toast('In die Zwischenablage kopiert')}catch(e){toast('Kopieren nicht möglich – Text bitte markieren')}}\n$('#mailLink').addEventListener('click',e=>{if(RN){e.preventDefault();rnPost({type:'open',url:$('#mailLink').href})}});\n$('#copySum').onclick=()=>copy($('#sumText').textContent);\n\n/* ============ Teilen ============ */\nfunction openShare(src,p,it){\n  $('#shareImg').src=src;\n  const shareTxt=`Schau mal, so sähe unser neuer Boden aus: ${p.name} (${p.line}), verlegt ${Math.round(it.angle)}°, ca. ${(it.W*it.D).toFixed(1)} m².\\nGeplant mit dem Naki Bodenplaner – ${CONFIG.website}`;\n  if(RN){rnPost({type:'share',image:src,text:shareTxt,title:p.name});return}\n  $('#shareText').textContent=shareTxt;\n  $('#mShare').classList.add('on');\n}\n$('#copyShare').onclick=()=>copy($('#shareText').textContent);\n$$('.modal').forEach(m=>m.addEventListener('click',e=>{if(e.target===m||e.target.hasAttribute('data-close'))m.classList.remove('on')}));\ndocument.addEventListener('keydown',e=>{if(e.key==='Escape')$$('.modal').forEach(m=>m.classList.remove('on'))});\n\n/* ============ Start ============ */\nlet isDemo=true;\nif(initGL()){\n  buildHandles();buildFilters();buildCatalog();updCount();\n  const d=demoRoom();setPhoto(d.canvas,d.quad,d.dims);setAngle(0);\n  selectProduct(CATALOG[0],true).then(()=>showHint('Wähle einen Boden – oder lade ein Foto deines Raums hoch',4500));\n}\n</script>\n</body>\n</html>\n";
export default html;
